  "title": "Paid reporting year",
  "brief": "Paid work inside one reporting year, with the year's edges defined exactly rather than approximately.",
  "instructions": [
    "Return the IDs of orders whose own status column is 'paid', from 2024-01-01 00:00:00 UTC onward and strictly before 2025-01-01 00:00:00 UTC. The payments table has a status of its own; this challenge does not ask about it.",
    "Include timestamps at or after 2024-01-01 00:00:00 UTC and exclude timestamps at or after 2025-01-01 00:00:00 UTC. The interval is half open.",
    "Return only the declared columns, in their declared order and exact SQL types, and follow the stated ordering contract. NULL placement is declared, not assumed."
  ],
  "datasetId": "commerce-practice",
  "starterSql": "SELECT order_id,status,ordered_at FROM orders LIMIT 10;",
  "starterExplanation": "The starter reads order_id, status and ordered_at out of orders. It runs. It does not answer the question. Reworded by sw-smoke.",
  "hints": [
    {
      "level": 1,
      "kind": "concept",
      "text": "Two conditions apply: the status, and a half-open interval in time."
    },
    {
      "level": 2,
      "kind": "structure",
      "text": "The lower bound is inclusive and the upper bound is not, so a closed range will not do."
    },
    {
      "level": 3,
      "kind": "boundary",
      "text": "Order 1 sits on the included edge; order 10 sits on the excluded one."
    }
  ],
  "dataClaims": [
    {
      "variant": "boundary",
      "sql": "SELECT (count(*) FILTER (WHERE order_id = 1 AND ordered_at >= TIMESTAMPTZ '2024-01-01 00:00:00+00' AND ordered_at < TIMESTAMPTZ '2025-01-01 00:00:00+00'))::VARCHAR || '/' || (count(*) FILTER (WHERE order_id = 10 AND ordered_at >= TIMESTAMPTZ '2024-01-01 00:00:00+00' AND ordered_at < TIMESTAMPTZ '2025-01-01 00:00:00+00'))::VARCHAR FROM orders",
      "equals": "1/0",
      "claim": "hints[2]: order 1 is inside UTC 2024 and order 10 is outside it"
    }
  ],
  "output": {
    "columns": [
      {
        "name": "order_id",
        "type": "BIGINT",
        "nullable": false
      }
    ],
    "ordering": [
      {
        "column": "order_id",
        "direction": "ASC",
        "nulls": "LAST"
      }
    ]
  },
  "reference": "/bundle/challenges/basics.02/reference.sql",
